#if UNITY_EDITOR
using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEditor;
namespace FashionFit.Editor {
 public static class MensRackVerification {
  public static void RunBatch(){GameObject root=null;var mode=Physics.simulationMode;string output=Path.GetFullPath("Verification/HollisterMens");try{Physics.simulationMode=SimulationMode.Script;root=new GameObject("Mens rack actual carry and release");var app=root.AddComponent<FashionFitApp>();typeof(FashionFitApp).GetMethod("Start",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(app,null);if(!app.Ready)throw new Exception(app.FatalError);app.Player.EnsureHands();var hands=app.Player.Hands;app.Player.PreviewVRMenu();var menu=app.Player.VRMenu;menu.SelectPage(11);var camera=app.Player.View;camera.rect=new Rect(0,0,1,1);camera.fieldOfView=60;camera.transform.position=menu.transform.position-menu.transform.forward*1.15f;camera.transform.LookAt(menu.transform.position,Vector3.up);Capture(camera,output+"/VRMenu.png");menu.Hide();app.PoseStudio.SetHandles(false);app.MaterialLab.ShowReadings=false;hands.Hide();camera.transform.position=new Vector3(1.0f,1.35f,1.05f);camera.transform.LookAt(new Vector3(3.63f,1.15f,1.05f));Capture(camera,output+"/MensRack.png");RunwayPickup item=null;foreach(var p in app.Showroom.Items)if(p.Look==7){item=p;break;}if(!item)throw new Exception("No mens rack item");Vector3 start=item.FittingPoint;Physics.SyncTransforms();hands.Step(0,true,start,Quaternion.identity,0,0,.02f);hands.Step(0,true,start,Quaternion.identity,1,0,.02f);if(hands.HeldBy(0)!=item.GetComponent<RunwayVRGrabTarget>())throw new Exception("Actual near Grip cannot pick up rack sample");Vector3 goal=app.PoseStudio.Rigs[1].Avatar.transform.TransformPoint(new Vector3(0,1.25f,.1f));for(int i=0;i<140;i++){hands.Step(0,true,Vector3.Lerp(start,goal,Mathf.Min(1,i/75f)),Quaternion.identity,1,0,.02f);item.StepHeld(.02f);Physics.Simulate(.02f);Physics.SyncTransforms();}hands.Release(0,false);if(app.PoseStudio.Wearables[1].Look!=7||app.Showroom.OutfitTarget!=2)throw new Exception("Releasing carried rack sample near male does not equip");File.WriteAllText(output+"/rack.json","{\"status\":\"passed\",\"scope\":\"Actual near-hand acquisition, interpolated carry with PhysX, and release equip; injected Touch, no physical HMD\",\"checks\":3}");UnityEngine.Object.DestroyImmediate(root);Physics.simulationMode=mode;EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText(output+"/rack_failure.txt",e.ToString());Debug.LogException(e);if(root)UnityEngine.Object.DestroyImmediate(root);Physics.simulationMode=mode;EditorApplication.Exit(1);}}
  static void Capture(Camera c,string path){var rt=new RenderTexture(1400,1000,24);var t=new Texture2D(1400,1000,TextureFormat.RGB24,false);var old=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;t.ReadPixels(new Rect(0,0,1400,1000),0,0);t.Apply();File.WriteAllBytes(path,t.EncodeToPNG());}finally{c.targetTexture=null;RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);}}
 }
}
#endif
